#!/usr/bin/env python3
"""Compile-check the Diesel code generated for the test fixtures.

For each database provider used by test/fixtures/*.prisma, this creates a
temporary Cargo project that depends on diesel with that backend, generates
schema.rs/models.rs for every fixture through the prismax CLI (dist/cli.js,
so run `pnpm build` first) into its own module, and runs `cargo check`.

Exits 0 with a message when cargo is not installed. CARGO_TARGET_DIR is
honored when set; otherwise the projects share a target directory inside the
work directory. `cargo check` never links, so the MySQL client library is not
needed: unless MYSQLCLIENT_LIB_DIR is set, mysqlclient-sys is pointed at an
empty directory. Python 3.9+, standard library only.
"""

from __future__ import annotations

import argparse
import os
import re
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path
from typing import Callable, Optional, Sequence

ROOT = Path(__file__).resolve().parent.parent
CLI = ROOT / "dist" / "cli.js"
FIXTURES = ROOT / "test" / "fixtures"

# Diesel backend feature per Prisma provider; other providers are skipped.
BACKENDS = {"postgresql": "postgres", "mysql": "mysql", "sqlite": "sqlite"}
# Features and crates for the Rust types the adapter emits.
DIESEL_VERSION = "2.2"
EXTRA_FEATURES = ["chrono", "serde_json", "uuid", "numeric"]
EXTRA_CRATES = {"chrono": "0.4", "serde_json": "1", "uuid": "1", "bigdecimal": "0.4"}

Runner = Callable[..., "subprocess.CompletedProcess[str]"]

_DATASOURCE = re.compile(r"datasource\s+\w+\s*\{(?P<body>[^}]*)\}", re.S)
_PROVIDER = re.compile(r'^\s*provider\s*=\s*"(?P<provider>[^"]+)"', re.M)


def detect_provider(schema: str) -> Optional[str]:
    """Returns the datasource provider of a schema, or None."""
    block = _DATASOURCE.search(schema)
    if block is None:
        return None
    match = _PROVIDER.search(block.group("body"))
    return match.group("provider") if match else None


def module_name(fixture: Path) -> str:
    """A Rust module name for a fixture file."""
    name = re.sub(r"\W", "_", fixture.stem).lower()
    return f"fixture_{name}"


def group_fixtures(fixtures: Sequence[Path]) -> tuple[dict[str, list[Path]], list[str]]:
    """Groups fixtures by provider. Returns (groups, messages about skipped fixtures)."""
    groups: dict[str, list[Path]] = {}
    skipped: list[str] = []
    for fixture in sorted(fixtures):
        provider = detect_provider(fixture.read_text(encoding="utf-8"))
        if provider not in BACKENDS:
            skipped.append(f"skip {fixture.name}: provider {provider!r} has no Diesel backend")
            continue
        groups.setdefault(provider, []).append(fixture)
    return groups, skipped


def cargo_toml(provider: str) -> str:
    features = ", ".join(f'"{f}"' for f in [BACKENDS[provider], *EXTRA_FEATURES])
    crates = "\n".join(f'{name} = "{version}"' for name, version in EXTRA_CRATES.items())
    return f"""[package]
name = "prismax-compile-check-{provider}"
version = "0.0.0"
edition = "2021"
publish = false

[lib]
path = "src/lib.rs"

[dependencies]
diesel = {{ version = "{DIESEL_VERSION}", features = [{features}] }}
{crates}
"""


def lib_rs(modules: Sequence[str]) -> str:
    lines = ["// Generated by scripts/compile_check_diesel.py.", "#![allow(dead_code)]", ""]
    lines += [f"pub mod {m};" for m in modules]
    return "\n".join(lines) + "\n"


MOD_RS = "pub mod schema;\npub mod models;\n"


def check_env(provider: str, base: dict[str, str], workdir: Path) -> dict[str, str]:
    """Environment for `cargo check` of one provider's project."""
    env = dict(base)
    env.setdefault("CARGO_TARGET_DIR", str(workdir / "target"))
    if provider == "mysql" and "MYSQLCLIENT_LIB_DIR" not in env:
        # mysqlclient-sys' build script only needs to know where the library would be.
        placeholder = workdir / "mysqlclient-placeholder"
        placeholder.mkdir(parents=True, exist_ok=True)
        env["MYSQLCLIENT_LIB_DIR"] = str(placeholder)
        env.setdefault("MYSQLCLIENT_VERSION", "8.0.36")
    return env


def create_project(project: Path, provider: str, fixtures: Sequence[Path], run: Runner, node: str) -> None:
    """Writes the Cargo project and generates code for each fixture with the CLI."""
    src = project / "src"
    src.mkdir(parents=True, exist_ok=True)
    (project / "Cargo.toml").write_text(cargo_toml(provider), encoding="utf-8")
    modules = []
    for fixture in fixtures:
        module = module_name(fixture)
        modules.append(module)
        out = src / module
        out.mkdir(exist_ok=True)
        (out / "mod.rs").write_text(MOD_RS, encoding="utf-8")
        command = [node, str(CLI), "generate", "--adapter", "diesel", "--schema", str(fixture), "--out", str(out)]
        result = run(command, capture_output=True, text=True)
        if result.returncode != 0:
            raise RuntimeError(f"prismax failed for {fixture.name} (exit {result.returncode}):\n{result.stderr}")
    (src / "lib.rs").write_text(lib_rs(modules), encoding="utf-8")


def main(
    argv: Optional[Sequence[str]] = None,
    which: Callable[[str], Optional[str]] = shutil.which,
    run: Runner = subprocess.run,
) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("fixtures", nargs="*", type=Path, help="schemas to check (default: test/fixtures/*.prisma)")
    parser.add_argument("--workdir", type=Path, help="keep the generated projects in this directory")
    args = parser.parse_args(argv)

    cargo = which("cargo")
    if cargo is None:
        print("cargo not found; skipping the Diesel compile check")
        return 0
    node = which("node")
    if node is None:
        print("error: node not found", file=sys.stderr)
        return 1
    if not CLI.exists():
        print(f"error: {CLI.relative_to(ROOT)} is missing; run `pnpm build` first", file=sys.stderr)
        return 1

    groups, skipped = group_fixtures(args.fixtures or sorted(FIXTURES.glob("*.prisma")))
    for message in skipped:
        print(message)
    if not groups:
        print("no fixtures to check")
        return 0

    workdir = args.workdir or Path(tempfile.mkdtemp(prefix="prismax-diesel-"))
    target = os.environ.get("CARGO_TARGET_DIR", str(workdir / "target"))
    print(f"work directory: {workdir}\ntarget directory: {target}")
    failures = []
    try:
        for provider, fixtures in groups.items():
            project = workdir / provider
            print(f"== {provider}: {', '.join(f.name for f in fixtures)}")
            try:
                create_project(project, provider, fixtures, run, node)
            except RuntimeError as error:
                print(error, file=sys.stderr)
                failures.append(provider)
                continue
            env = check_env(provider, dict(os.environ), workdir)
            result = run([cargo, "check", "--quiet", "--message-format", "short"], cwd=project, env=env, text=True)
            if result.returncode != 0:
                failures.append(provider)
    finally:
        if args.workdir is None:
            shutil.rmtree(workdir, ignore_errors=True)

    if failures:
        print(f"FAILED: {', '.join(failures)}", file=sys.stderr)
        return 1
    print("OK: generated Diesel code compiles")
    return 0


if __name__ == "__main__":
    sys.exit(main())
